"  const getStaffPermissions = () => {
    if (!business || !business.staff_permissions) return {};
    if (typeof business.staff_permissions === 'string') {
      try {
        return JSON.parse(business.staff_permissions);
      } catch (e) {
        return {};
      }
    }
    return business.staff_permissions;
  };

  const verifyPasscodeAction = (modules, action, callback, name) => {
    const permissions = getStaffPermissions();
    const posAccess = permissions.pos_access || {};

    const checkPermission = (obj, key) => {
      if (!obj || typeof obj !== 'object') return false;
      if (obj[key] === true) return true;
      for (const subKey in obj) {
        if (typeof obj[subKey] === 'object') {
          if (checkPermission(obj[subKey], key)) return true;
        }
      }
      return false;
    };

    const isOwnerOrAdmin = business && ['master_admin', 'brand_owner', 'admin', 'owner'].includes(business.role);
    let hasDirectPermission = isOwnerOrAdmin || checkPermission(posAccess, action);

    if (hasDirectPermission) {
      callback();
      return;
    }

    let passcodeAllowed = checkPermission(posAccess, action + '_passcode');

    if (!passcodeAllowed) {
      toast.error(`Access Denied: You do not have permission to ${name.toLowerCase()}`);
      return;
    }

    setPasscodeModalState({
      isOpen: true,
      requiredModules: modules,
      actionKey: action,
      onSuccess: callback,
      actionName: name
    });
  };"

